"""Build an offline visual preview with an explicit simulated update backend."""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
out=root/'dist/previews/Clawd-Update-Flow-Lab.html'
card=re.search(r'<main.*?</main>',(root/'web/updates.html').read_text(encoding='utf-8'),re.S)[0]
css=(root/'web/updates.css').read_text(encoding='utf-8')+'''body{padding:22px 14px;background:#f5f2eb}.preview{max-width:1120px;margin:auto}.preview h1{font-size:22px;margin:0 0 6px}.intro{font-size:13px;line-height:1.7;color:#8a7860;margin:0 0 16px}.work-area{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:20px;align-items:center;background:#faf7f0;border:1px solid #ded5c5;border-radius:16px;padding:18px}.pet-scene svg{display:block;width:100%;max-height:440px}.dialog-host .update-card{min-height:370px;background:#f8f4eb;box-shadow:4px 4px 0 #c9bca650}.idle-note{padding:25px;text-align:center;color:#9b8a70;line-height:1.8}.scenarios{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0 12px}.preview button{font:13px/1.6 system-ui;border:1px solid #d3c6b2;background:#eee6d8;color:#655442;padding:8px 13px;border-radius:5px;cursor:pointer}.preview button:first-child{background:#d97757;border-color:#d97757;color:#fff}.preview .update-card button{border-radius:3px}.preview .update-card .primary{background:#d97757;color:#fff}.daily{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:13px;color:#8a7860;border-top:1px solid #ddd2c0;padding-top:14px}.daily label{display:flex;gap:5px;align-items:center}.daily small{flex-basis:100%}.key.is-down .key-top{fill:#f2bf72}@media(max-width:800px){.work-area{grid-template-columns:1fr}.dialog-host{max-width:440px;width:100%;margin:auto}.idle-note{padding:8px}.pet-scene svg{max-height:370px}.work-area{padding:10px}.preview h1{font-size:20px}}'''
scripts=[(root/p).read_text(encoding='utf-8') for p in ['web/core/clawd.bundle.js','web/core/clawd-update-visuals.js','web/update-dialog.js','web/update-preview.js']]
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clawd · 更新流程预览</title><style>'''+css+'''</style></head><body><div class="preview"><h1>小蟹的新版本，正在路上 🪄</h1><p class="intro">这是离线流程预览：版本、更新日志与下载进度均为模拟，不会联网下载或安装。选「发现新版」，再点小窗里的更新按钮，可以看完全过程。</p><div class="work-area"><main id="update-preview"><div class="pet-scene">'''+(root/'web/clawd-scene.svg').read_text(encoding='utf-8')+'''</div><span data-status hidden></span><span data-last-key hidden></span></main><section class="dialog-host" hidden>'''+card+'''</section><p class="idle-note" data-idle-note></p></div><div class="scenarios"><button type="button" data-update-scenario="found">发现新版 · 完整流程</button><button type="button" data-update-scenario="current">已经是最新版</button><button type="button" data-update-scenario="check-error">检查阶段失败</button><button type="button" data-update-scenario="download-error">下载中途失败</button><button type="button" data-update-scenario="success">只看魔法棒庆祝</button></div><div class="daily"><label><input type="checkbox" data-auto-check checked>每天首次启动自动检查</label><button type="button" data-simulate-start>模拟重新打开应用</button><button type="button" data-new-day>清除今日预览记录</button><label><input type="checkbox" data-sound checked>提示音</label><small data-daily-status></small></div></div><script type="application/json" id="clawd-rig-data">'''+(root/'web/rig-data.json').read_text(encoding='utf-8')+'''</script>'''+''.join('<script>'+s+'</script>' for s in scripts)+'''</body></html>'''
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(page,encoding='utf-8',newline='\n');print(out)
